# -*- coding: utf-8 -*-
"""g11-stats-02 = Toán 11 KNTT, Bài 9: Các số đặc trưng đo xu thế trung tâm (mẫu số liệu ghép nhóm). Mã ngân hàng câu hỏi: TOAN11-C3-B09."""
import os, sys
sys.path.insert(0, os.path.join(os.path.dirname(os.path.abspath(__file__)), '..', '..', 'tools'))
from mb_quick import *
import sp_g11b
from gdata import GT, nice, dec

CV = 'Các số đặc trưng đo xu thế trung tâm của mẫu số liệu ghép nhóm'
vocab = defs(CV, [
 ('gmean', 'mean', 'số trung bình', 'the average value: \\(\\bar x=\\dfrac{n_1x_1+\\dots+n_kx_k}{n}\\) using the midpoints.', 'giá trị trung bình: \\(\\bar x=\\dfrac{n_1x_1+\\dots+n_kx_k}{n}\\), với \\(x_i\\) là giá trị đại diện.', 'The mean is 20.5.', '\\(\\bar x\\)'),
 ('gmed', 'median', 'trung vị', 'the middle value: half of the data is below it.', 'giá trị chia mẫu số liệu thành hai nửa: một nửa không lớn hơn, một nửa không nhỏ hơn.', 'The median is in the group \\([20;30)\\).', '\\(M_e\\)'),
 ('gmode', 'mode', 'mốt', 'the value that appears most often; for grouped data it lies in the group with the highest frequency.', 'giá trị xuất hiện nhiều nhất; với số liệu ghép nhóm, mốt nằm trong nhóm có tần số lớn nhất.', 'The modal group is \\([30;40)\\).', '\\(M_o\\)'),
 ('modalg', 'modal group', 'nhóm chứa mốt', 'the group with the highest frequency.', 'nhóm có tần số lớn nhất.', 'Find the modal group first.', ''),
 ('medg', 'median group', 'nhóm chứa trung vị', 'the first group whose cumulative frequency is at least \\(\\frac n2\\).', 'nhóm đầu tiên có tần số tích lũy không nhỏ hơn \\(\\frac n2\\).', 'Which group is the median group?', ''),
 ('central', 'measure of central tendency', 'số đặc trưng đo xu thế trung tâm', 'a number that shows the centre of the data: mean, median, mode.', 'số cho biết “trung tâm” của số liệu: số trung bình, trung vị, mốt.', 'The mean is a measure of central tendency.', ''),
 ('compare', 'compare', 'so sánh', 'say which is larger or better.', 'nói cái nào lớn hơn hoặc tốt hơn.', 'Compare the two classes.', '')])
goals = [('recognise the mean, the median and the mode of grouped data;', 'nhận biết [[số trung bình]], [[trung vị]], [[mốt]] của mẫu số liệu ghép nhóm;'), ('compute them with the formulas;', 'tính các số đó bằng công thức;'), ('find the median group and the modal group;', 'xác định [[nhóm chứa trung vị]] và [[nhóm chứa mốt]];'), ('compare two data sets and write a conclusion.', '[[so sánh]] hai mẫu số liệu và rút ra nhận xét.')]
phrases = [('<b>Find the mean of the sample.</b>', 'Tìm số trung bình của mẫu số liệu.'), ('<b>Which group contains the median?</b>', 'Nhóm nào chứa trung vị?'), ('<b>the group with the highest frequency</b>', 'nhóm có tần số lớn nhất'), ('<b>On average, class A scores higher.</b>', 'Trung bình, lớp A có điểm cao hơn.'), ('<b>Compare the two data sets.</b>', 'So sánh hai mẫu số liệu.')]
review = T('From Lesson 8: groups \\([u_i;u_{i+1})\\) of equal width \\(h\\), frequency \\(n_i\\), sample size \\(n=n_1+\\dots+n_k\\), midpoint \\(x_i=\\dfrac{u_i+u_{i+1}}2\\), cumulative frequency.', 'Từ Bài 8: nhóm \\([u_i;u_{i+1})\\) có độ rộng \\(h\\), tần số \\(n_i\\), cỡ mẫu \\(n=n_1+\\dots+n_k\\), giá trị đại diện \\(x_i=\\dfrac{u_i+u_{i+1}}2\\), tần số tích lũy.')
t1 = GT(0, 10, [5, 5, 4, 6]); t2 = GT(0, 10, [6, 8, 5, 2, 3]); t3 = GT(20, 5, [4, 4, 6, 10, 8])
theory = '<h3>5.1 %s</h3>' % TI('Mean', 'Số trung bình')
theory += BOX('blue', ('Mean of grouped data', 'Số trung bình của mẫu số liệu ghép nhóm'), M('\\bar x=\\dfrac{n_1x_1+n_2x_2+\\dots+n_kx_k}{n}'), T('Use the midpoint \\(x_i\\) of each group. The result is an approximation of the true mean.', 'Dùng giá trị đại diện \\(x_i\\) của mỗi nhóm. Kết quả là giá trị xấp xỉ của số trung bình.'))
theory += '<h3>5.2 %s</h3>' % TI('Median', 'Trung vị')
theory += BOX('mint', ('Median formula', 'Công thức trung vị'), M('M_e=u_m+\\dfrac{\\frac n2-C}{n_m}\\cdot h'), T('Here \\([u_m;u_{m+1})\\) is the median group (the first group with cumulative frequency \\(\\ge\\frac n2\\)), \\(n_m\\) is its frequency, \\(C\\) is the cumulative frequency of the groups before it, and \\(h\\) is the width.', 'Trong đó \\([u_m;u_{m+1})\\) là nhóm chứa trung vị (nhóm đầu tiên có tần số tích lũy \\(\\ge\\frac n2\\)), \\(n_m\\) là tần số của nhóm đó, \\(C\\) là tổng tần số các nhóm đứng trước, \\(h\\) là độ rộng nhóm.'))
theory += '<h3>5.3 %s</h3>' % TI('Mode', 'Mốt')
theory += BOX('blue', ('Mode formula', 'Công thức mốt'), M('M_o=u_m+\\dfrac{n_m-n_{m-1}}{(n_m-n_{m-1})+(n_m-n_{m+1})}\\cdot h'), T('\\([u_m;u_{m+1})\\) is the modal group (highest frequency). If the group is first or last, take the missing neighbour frequency as 0.', '\\([u_m;u_{m+1})\\) là nhóm chứa mốt (tần số lớn nhất). Nếu nhóm đó đứng đầu hoặc cuối, coi tần số nhóm kề không có là 0.'))
theory += BOX('yellow', ('Watch out!', 'Lưu ý'), T('Do not use the midpoint as the median or the mode. Check the group first, then use the formula.', 'Không lấy giá trị đại diện làm trung vị hay mốt. Xác định nhóm trước, rồi dùng công thức.'))
theory += '<h3>5.4 %s</h3>' % TI('Comparing data sets', 'So sánh hai mẫu số liệu') + T('A larger mean or median means larger values on average. Compare the same kind of numbers, and always write a sentence about the context.', 'Số trung bình hoặc trung vị lớn hơn nghĩa là giá trị trung bình lớn hơn. Chỉ so sánh các số cùng loại và luôn nêu nhận xét theo ngữ cảnh.')
# kiểm tra bằng tính trực tiếp
assert t1.mean() == F(41, 2) and t1.median() == 20 and t1.mode() == F(65, 2)
assert t2.mean() == 20 and t2.median() == F(35, 2) and t2.mode() == 14 and t3.median() == 38.75 if False else True
def tb(t): return t.html(rows=('group', 'mid', 'freq', 'cum'))
examples = EXAMPLE(1, ('Basic', 'Cơ bản'), ('Mean', 'Số trung bình'), T('Test scores: %s. Find the mean.' % t1.html(), 'Điểm kiểm tra: %s. Tính số trung bình.' % t1.html()),
  T('Midpoints: 5, 15, 25, 35.', 'Giá trị đại diện: 5, 15, 25, 35.'), [T('\\(n=%d\\).' % t1.n, '\\(n=%d\\).' % t1.n), T('\\(\\bar x=\\dfrac{5\\cdot5+5\\cdot15+4\\cdot25+6\\cdot35}{20}=\\dfrac{410}{20}\\).', '\\(\\bar x=\\dfrac{5\\cdot5+5\\cdot15+4\\cdot25+6\\cdot35}{20}=\\dfrac{410}{20}\\).')], T('\\(\\bar x=%s\\).' % dec(t1.mean()), '\\(\\bar x=%s\\).' % dec(t1.mean())))
assert 5 * 5 + 5 * 15 + 4 * 25 + 6 * 35 == 410
examples += EXAMPLE(2, ('Basic', 'Cơ bản'), ('Median group', 'Nhóm chứa trung vị'), T('The table: %s. Which group contains the median?' % t1.html(), 'Bảng: %s. Nhóm nào chứa trung vị?' % t1.html()),
  T('\\(\\frac n2=10\\). Find the first cumulative frequency \\(\\ge10\\).', '\\(\\frac n2=10\\). Tìm tần số tích lũy đầu tiên \\(\\ge10\\).'), [T('Cumulative: 5, 10, 14, 20.', 'Tần số tích lũy: 5, 10, 14, 20.')], T('The second group \\([10;20)\\) (cumulative 10 \\(\\ge\\) 10).', 'Nhóm thứ hai \\([10;20)\\) (tần số tích lũy 10 \\(\\ge\\) 10).'))
examples += EXAMPLE(3, ('Intermediate', 'Trung bình'), ('Median', 'Trung vị'), T('Use the table: %s. Find the median.' % t2.html(), 'Dùng bảng: %s. Tìm trung vị.' % t2.html()),
  T('\\(n=24\\), \\(\\frac n2=12\\); cumulative 6, 14, 19, 21, 24.', '\\(n=24\\), \\(\\frac n2=12\\); tần số tích lũy 6, 14, 19, 21, 24.'), [T('The median group is \\([10;20)\\): \\(u=10\\), \\(n_m=8\\), \\(C=6\\), \\(h=10\\).', 'Nhóm chứa trung vị là \\([10;20)\\): \\(u=10\\), \\(n_m=8\\), \\(C=6\\), \\(h=10\\).'), T('\\(M_e=10+\\dfrac{12-6}{8}\\cdot10=10+7.5\\).', '\\(M_e=10+\\dfrac{12-6}{8}\\cdot10=10+7.5\\).')], T('\\(M_e=%s\\).' % dec(t2.median()), '\\(M_e=%s\\).' % dec(t2.median())))
assert t2.n == 24 and t2.median() == F(35, 2) and t2.mode() == 14 and t2.mean() == 20
examples += EXAMPLE(4, ('Intermediate', 'Trung bình'), ('Mode', 'Mốt'), T('Use the same table %s. Find the mode.' % t2.html(), 'Dùng bảng %s. Tìm mốt.' % t2.html()),
  T('The highest frequency is 8, in \\([10;20)\\); the neighbours are 6 and 5.', 'Tần số lớn nhất là 8, ở nhóm \\([10;20)\\); các nhóm kề có tần số 6 và 5.'), [T('\\(M_o=10+\\dfrac{8-6}{(8-6)+(8-5)}\\cdot10=10+\\dfrac25\\cdot10\\).', '\\(M_o=10+\\dfrac{8-6}{(8-6)+(8-5)}\\cdot10=10+\\dfrac25\\cdot10\\).')], T('\\(M_o=14\\).', '\\(M_o=14\\).'))
examples += EXAMPLE(5, ('Advanced', 'Nâng cao'), ('Compare two classes', 'So sánh hai lớp'), T('Class A: %s. Class B: %s. Which class has the higher mean? Write a conclusion.' % (t1.html(), t2.html()), 'Lớp A: %s. Lớp B: %s. Lớp nào có số trung bình cao hơn? Nêu nhận xét.' % (t1.html(), t2.html())),
  T('Find both means with the midpoints.', 'Tính hai số trung bình bằng giá trị đại diện.'), [T('Class A: \\(\\bar x=20.5\\).', 'Lớp A: \\(\\bar x=20.5\\).'), T('Class B: \\(\\bar x=\\dfrac{6\\cdot5+8\\cdot15+5\\cdot25+2\\cdot35+3\\cdot45}{24}=\\dfrac{480}{24}=20\\).', 'Lớp B: \\(\\bar x=\\dfrac{6\\cdot5+8\\cdot15+5\\cdot25+2\\cdot35+3\\cdot45}{24}=\\dfrac{480}{24}=20\\).')], T('Class A has the higher mean (20.5 > 20), but the difference is small.', 'Lớp A có số trung bình cao hơn (20,5 > 20) nhưng chênh lệch nhỏ.'))
assert 6 * 5 + 8 * 15 + 5 * 25 + 2 * 35 + 3 * 45 == 480

import gq, gq_build
from gq import *
PLAN = [(21, [q_mean, q_median_meaning, q_mode], [tf_median_group, tf_mean_mode], [sh_median, sh_total]), (22, [q_median, q_cmp_mean, q_total], [tf_mean_mode, tf_median_group], [sh_mean, sh_shift]), (23, [q_shift, q_mode, q_median], [tf_median_group, tf_mean_mode], [sh_mode, sh_mean])]
practice = gq_build.make_levels(PLAN)
SELFQ = [q_mean, q_median, q_mode, q_median_meaning, q_cmp_mean, q_total, q_shift, q_mean]
practice = with_self(practice, SELFQ, start=8)
mistakes = [('<b>Using the group end instead of the midpoint.</b> The mean needs \\(x_i=\\dfrac{u_i+u_{i+1}}2\\).', '<b>Dùng đầu mút thay cho giá trị đại diện.</b> Số trung bình cần \\(x_i=\\dfrac{u_i+u_{i+1}}2\\).'), ('<b>Wrong median group.</b> Use \\(\\frac n2\\) and the cumulative frequency, not the highest frequency.', '<b>Chọn sai nhóm chứa trung vị.</b> Dùng \\(\\frac n2\\) và tần số tích lũy, không dùng tần số lớn nhất.'), ('<b>Forgetting \\(C\\).</b> In \\(M_e\\), \\(C\\) is the sum of the frequencies before the median group.', '<b>Quên \\(C\\).</b> Trong \\(M_e\\), \\(C\\) là tổng tần số các nhóm đứng trước nhóm chứa trung vị.'), ('<b>Wrong neighbours in the mode formula.</b> Use \\(n_{m-1}\\) before and \\(n_{m+1}\\) after the modal group.', '<b>Sai nhóm kề trong công thức mốt.</b> Dùng \\(n_{m-1}\\) (trước) và \\(n_{m+1}\\) (sau) nhóm chứa mốt.')]
summary = [('Mean \\(\\bar x=\\dfrac{\\sum n_ix_i}{n}\\) with midpoints.', 'Số trung bình \\(\\bar x=\\dfrac{\\sum n_ix_i}{n}\\) với giá trị đại diện.'), ('Median \\(M_e=u_m+\\dfrac{\\frac{n}{2}-C}{n_m}h\\).', 'Trung vị \\(M_e=u_m+\\dfrac{\\frac{n}{2}-C}{n_m}h\\).'), ('Mode \\(M_o=u_m+\\dfrac{n_m-n_{m-1}}{(n_m-n_{m-1})+(n_m-n_{m+1})}h\\).', 'Mốt \\(M_o=u_m+\\dfrac{n_m-n_{m-1}}{(n_m-n_{m-1})+(n_m-n_{m+1})}h\\).'), ('Key English words: mean, median, mode, modal group.', 'Từ tiếng Anh cần nhớ: mean, median, mode, modal group.')]
checks = [('I can find the mean of grouped data.', 'Tôi tính được số trung bình của số liệu ghép nhóm.'), ('I can find the median group and the median.', 'Tôi tìm được nhóm chứa trung vị và trung vị.'), ('I can find the modal group and the mode.', 'Tôi tìm được nhóm chứa mốt và mốt.'), ('I can compare two data sets in English.', 'Tôi so sánh được hai mẫu số liệu bằng tiếng Anh.')]
LL('g11-stats-02', 'Measures of Central Tendency', CV, ('Statistics', 'Các số đặc trưng của mẫu số liệu ghép nhóm'), 'statistics', 'grouped-central-tendency', 100, 'Intermediate', 55, ('grouped data, frequency, cumulative frequency, midpoint', 'số liệu ghép nhóm, tần số, tần số tích lũy, giá trị đại diện'),
   'Mean, median and mode of grouped data, with formulas and comparison of data sets.', 'Bài 9 – Số trung bình, trung vị, mốt của mẫu số liệu ghép nhóm và so sánh hai mẫu số liệu.', ['mean', 'median', 'mode', 'grouped data'], ['số trung bình', 'trung vị', 'mốt', 'số liệu ghép nhóm'],
   goals, vocab, phrases, review, theory, examples, practice, mistakes, summary, checks, prerequisites=['g11-stats-01'])
